-- The PNG decoder used for Vista-style icons: a 32x32 RGBA image with
-- every scanline filter, compressed by zlib (dynamic Huffman blocks).
local png = require("win16.png")
local data = "\137\80\78\71\13\10\26\10\0\0\0\13\73\72\68\82\0\0\0\32\0\0\0\32\8\6\0\0\0\115\122\122\244\0\0\1\138\73\68\65\84\120\218\229\210\17\156\164\96\28\199\225\246\110\97\49\12\7\14\6\195\48\28\56\8\195\48\12\14\194\48\12\195\48\28\28\28\12\195\112\112\48\204\246\158\206\238\179\190\3\253\222\207\195\239\31\190\65\16\52\193\7\33\17\39\206\196\36\164\92\200\200\41\40\169\168\217\95\75\71\207\192\200\149\27\119\38\102\22\30\60\89\217\120\11\62\246\3\130\151\249\241\210\223\249\25\132\105\240\254\30\188\206\191\75\254\223\103\240\173\59\107\128\144\136\211\185\249\60\19\147\144\114\33\35\167\160\164\162\166\161\165\163\103\96\228\202\141\59\19\51\11\15\158\172\108\188\5\241\151\8\63\15\22\225\175\47\17\54\175\142\240\155\151\105\128\144\136\83\38\66\98\18\82\46\100\228\20\148\84\212\52\180\116\244\12\140\92\185\113\103\98\102\225\193\147\149\45\219\35\204\15\31\97\114\248\8\107\13\16\18\113\170\69\72\76\66\202\133\140\156\130\146\138\154\134\150\142\158\129\145\43\55\238\76\204\44\60\120\178\178\213\123\132\205\225\35\252\125\248\8\7\13\16\18\113\26\68\72\76\66\202\133\140\156\130\146\138\154\134\150\142\158\129\145\43\55\238\76\204\44\60\120\178\178\13\123\132\227\225\35\44\14\31\225\164\1\66\34\78\147\8\137\73\72\185\144\145\83\80\82\81\211\208\210\209\51\48\114\229\198\157\137\153\133\7\79\86\182\105\143\112\62\124\132\127\14\31\225\170\1\66\34\78\171\8\137\73\72\185\144\145\83\80\82\81\211\208\210\209\51\48\114\229\198\157\137\153\133\7\79\86\182\117\143\112\123\109\132\127\1\161\125\19\129\0\27\126\160\0\0\0\0\73\69\78\68\174\66\96\130"
local w, h, rows = png.decode(data)
assert(w == 32 and h == 32, "size")
for y = 0, 31 do
    for x = 0, 31 do
        local a = (x < 4 or y < 4) and 0 or 255
        local want = (a << 24) | (((x * 8) & 255) << 16) | (((y * 8) & 255) << 8) | 128
        assert(rows[y + 1][x + 1] == want, ("pixel %d,%d"):format(x, y))
    end
end
local dib = png.toIconDib(data)
assert(dib and string.unpack("<I4", dib) == 40, "dib header")
local _, dw, dh, _, bpp = string.unpack("<I4i4i4I2I2", dib)
assert(dw == 32 and dh == 64 and bpp == 32, "dib shape")
assert(#dib == 40 + 32 * 32 * 4 + 32 * 4, "dib length")
-- the icon converts to the 32x32 form Program Manager draws
local pe = require("win16.pe")
local ico = string.pack("<I2I2I2BBBBI2I2I4I4", 0, 1, 1, 32, 32, 0, 0, 1, 32, #data, 22) .. data
assert(pe.icoBytes(ico, require("win16.gdi")), "ico with a PNG image")
host.log("png ok")
return 0
